'use strict';
(function(){
 let editor=null,mountedItem=null,active=null,healthPromise=null;
 const results=new Map(),bundles=new Map();
 const mode={java:'text/x-java',python:'python',javascript:'javascript',typescript:'text/typescript'};
 const names={completed:'Completed',compile_error:'Compilation error',runtime_error:'Runtime error',timeout:'Time limit exceeded',stopped:'Stopped',output_limit:'Output limit exceeded',running:'Running',local_running:'Compiling / running',compiling:'Compiling',loading:'Loading runtime',unavailable:'Runtime unavailable'};
 const keyFor=item=>draftKey(item);
 function currentItem(){return route().path==='lab'?labQuestion().item:data.find(i=>i.id===route().id);}
 function getValue(){return editor?editor.getValue():document.querySelector('#lab-answer,#code-draft')?.value||'';}
 function stdInputKey(item){return 'stdin::'+keyFor(item);}
 function demo(language){return {java:'import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        long total = 0;\n        while (input.hasNextLong()) {\n            total += input.nextLong();\n        }\n        System.out.println(total);\n    }\n}\n',python:'numbers = [int(value) for value in input().split()]\nprint(sum(numbers))\n',javascript:'const numbers = readAll().trim().split(/\\s+/).filter(Boolean).map(Number);\nconsole.log(numbers.reduce((sum, value) => sum + value, 0));\n',typescript:'const numbers: number[] = readAll().trim().split(/\\s+/).filter(Boolean).map(Number);\nconst total: number = numbers.reduce((sum, value) => sum + value, 0);\nconsole.log(total);\n'}[language];}
 function filename(item){if(item.language==='java'){const match=getValue().match(/\bpublic\s+(?:(?:final|abstract)\s+)?(?:class|record|enum)\s+([A-Za-z_$][A-Za-z0-9_$]*)/);return (match?.[1]||'Main')+'.java';}return 'main.'+languageConfig[item.language].extension;}
 function lineStatus(){if(!editor)return;const cursor=editor.getCursor();const label=document.getElementById('editor-position');if(label)label.textContent='Ln '+(cursor.line+1)+', Col '+(cursor.ch+1);const file=document.getElementById('editor-filename');if(file)file.textContent=filename(mountedItem);}
 function paint(item,result){if(!mountedItem||keyFor(item)!==keyFor(mountedItem))return;const output=document.getElementById('run-output'),errors=document.getElementById('run-errors'),status=document.getElementById('execution-status');if(!output||!status)return;output.textContent=result.stdout||'';errors.textContent=result.stderr||'';errors.hidden=!result.stderr;output.classList.toggle('empty-output',!result.stdout);if(!result.stdout)output.textContent=['running','local_running','compiling','loading'].includes(result.status)?'Waiting for program output…':result.status==='completed'?'Program finished without standard output.':'Output will appear here.';status.textContent=names[result.status]||'Ready';status.dataset.status=result.status;const duration=document.getElementById('execution-duration');if(duration)duration.textContent=result.durationMs!==undefined?result.durationMs+' ms':'';const running=!!active&&active.key===keyFor(item);document.getElementById('run-code').disabled=running;document.getElementById('stop-code').disabled=!running;}
 function saveResult(run,result){const previous=results.get(run.key)||{};const merged={...previous,...result};results.set(run.key,merged);paint(run.item,merged);}
 function dispose(run){clearTimeout(run.timeout);if(run.listener)window.removeEventListener('message',run.listener);run.rejectLoad?.(new Error('Run closed.'));if(run.frame){const frame=run.frame;const cleanup=()=>{window.removeEventListener('message',closed);frame.remove();};const closed=event=>{if(event.source===frame.contentWindow&&event.data?.type==='closed'&&event.data?.runId===run.id)cleanup();};window.addEventListener('message',closed);frame.contentWindow?.postMessage({kind:'stop'},'*');setTimeout(cleanup,500);}}
 function finish(run,result){if(active!==run)return;dispose(run);active=null;saveResult(run,result);}
 function stop(silent=false){const run=active;if(!run)return;if(run.local){fetch('/api/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({runId:run.id})}).catch(()=>{});run.controller?.abort();}finish(run,{status:'stopped',stderr:silent?'Run stopped when the preparation context changed.':'Run stopped.',durationMs:Math.round(performance.now()-run.started)});}
 function setDeadline(run,milliseconds){clearTimeout(run.timeout);run.timeout=setTimeout(()=>{if(active!==run)return;if(run.local){fetch('/api/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({runId:run.id})}).catch(()=>{});run.controller?.abort();}finish(run,{status:'timeout',stderr:'Execution time limit exceeded. The run was stopped.',durationMs:Math.round(performance.now()-run.started)});},milliseconds);}
 async function runtimeHealth(){if(!healthPromise)healthPromise=fetch('/api/runtimes',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error();return r.json();}).catch(()=>null);return healthPromise;}
 async function bootstrap(language){const key=language==='typescript'?'typescript':'javascript';if(!bundles.has(key)){const files=key==='typescript'?['vendor/typescript/typescript.js','vendor/typescript/libs.js','runner-worker.js']:['runner-worker.js'];bundles.set(key,Promise.all(files.map(file=>fetch(file).then(r=>{if(!r.ok)throw new Error('Cannot load the bundled compiler. Serve this site with its local server.');return r.text();}))).then(parts=>parts.join('\n;\n')).catch(error=>{bundles.delete(key);throw error;}));}return bundles.get(key);}
 async function runBrowser(run,code,input){const load=bootstrap(run.item.language);const frame=document.createElement('iframe');frame.setAttribute('sandbox','allow-scripts');frame.setAttribute('aria-hidden','true');frame.title='Isolated code execution';frame.hidden=true;run.frame=frame;const ready=new Promise((resolve,reject)=>{run.rejectLoad=reject;frame.onload=resolve;frame.onerror=()=>reject(new Error('The isolated runner could not load.'));});frame.src='runner-frame.html';document.body.append(frame);setDeadline(run,25000);const [source]=await Promise.all([load,ready]);if(active!==run)return;run.listener=event=>{if(event.source!==frame.contentWindow||event.data?.runId!==run.id||active!==run)return;const message=event.data;if(message.type==='phase'){saveResult(run,{status:message.phase});setDeadline(run,message.phase==='running'?7000:18000);}else if(message.type==='output'){const result=results.get(run.key);const field=message.stream==='stderr'?'stderr':'stdout';const text=String(message.text||'');if((result.stdout.length+result.stderr.length+text.length)>70000){finish(run,{status:'output_limit',stderr:'Output limit exceeded.'});return;}saveResult(run,{[field]:result[field]+text});}else if(message.type==='result'){const previous=results.get(run.key);finish(run,{status:message.status||'runtime_error',stderr:(previous.stderr||'')+(message.stderr?String(message.stderr):''),durationMs:message.durationMs??Math.round(performance.now()-run.started),exitCode:message.exitCode});}};window.addEventListener('message',run.listener);frame.contentWindow.postMessage({kind:'run',runId:run.id,bootstrap:source,language:run.item.language,code,input},'*');}
 async function runLocal(run,code,input){run.local=true;run.controller=new AbortController();const health=await runtimeHealth();if(active!==run)return;if(!health?.[run.item.language]){healthPromise=null;finish(run,{status:'unavailable',stderr:'Java and Python need the bundled local compiler server. Start it with:\npython3 server/local_server.py --port 8796\n\nNo code was sent to an external service.'});return;}saveResult(run,{status:run.item.language==='java'?'local_running':'running'});setDeadline(run,22000);const response=await fetch('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({runId:run.id,language:run.item.language,code,input}),signal:run.controller.signal});const result=await response.json();if(active!==run)return;if(!response.ok)throw new Error(result.error||'Local execution failed.');finish(run,result);}
 async function run(){if(active||!mountedItem)return;editor?.save();const item=mountedItem,code=getValue(),input=document.getElementById('program-stdin').value;if(!code.trim()){toast('Write or load a program first.');return;}if(new TextEncoder().encode(code).length>131072||new TextEncoder().encode(input).length>65536){toast('Use at most 128 KiB of code and 64 KiB of standard input.');return;}const record={item,key:keyFor(item),id:crypto.randomUUID?crypto.randomUUID():'run-'+Date.now()+'-'+Math.random().toString(36).slice(2),started:performance.now()};active=record;results.set(record.key,{status:'loading',stdout:'',stderr:''});paint(item,results.get(record.key));try{if(['java','python'].includes(item.language))await runLocal(record,code,input);else await runBrowser(record,code,input);}catch(error){if(active!==record)return;finish(record,{status:'runtime_error',stderr:error.message||String(error),durationMs:Math.round(performance.now()-record.started)});}}
 function setCode(code,input){if(!mountedItem)return;const old=getValue();state.editorBackups=state.editorBackups||{};state.editorBackups[keyFor(mountedItem)]=old;persist();if(editor)editor.setValue(code);if(input!==undefined){document.getElementById('program-stdin').value=input;state.drafts[stdInputKey(mountedItem)]=input;persist();}lineStatus();toast('Code loaded. Use Undo or Restore draft to return to your previous work.');}
 window.compilerPanel=function(item){const config=languageConfig[item.language];return `<section class="execution-panel" aria-label="Code execution"><div class="execution-toolbar"><span class="file-label" id="editor-filename">${item.language==='java'?'Main.java':'main.'+config.extension}</span><span class="runtime-badge">${item.language==='typescript'?'TypeScript strict · ES2022':item.language==='java'?'Java 17 · local':'python'===item.language?'Python · local':'JavaScript · browser'}</span><div class="execution-buttons"><button class="button primary small" id="run-code">▶ Run code</button><button class="button small" id="stop-code" disabled>■ Stop</button></div></div><div class="editor-tools"><button class="button quiet small" id="load-demo">Load demo</button>${item.code&&item.solved?'<button class="button quiet small" id="load-solution">Load worked solution</button>':''}<button class="button quiet small" id="restore-code">Restore draft</button><button class="button quiet small" id="download-code">Download code ↓</button><span id="editor-position">Ln 1, Col 1</span></div><div class="execution-io"><div class="stdin-panel"><label for="program-stdin">STANDARD INPUT</label><textarea id="program-stdin" placeholder="Optional input for your program" spellcheck="false">${esc(state.drafts[stdInputKey(item)]||'')}</textarea><small>${['javascript','typescript'].includes(item.language)?'Use readAll() or readLine() for input. The fs.readFileSync(0, "utf8") form is also supported.':'Read input with '+(item.language==='java'?'Scanner / System.in.':'input() / sys.stdin.')}</small></div><div class="console-panel"><div class="console-heading"><label for="run-output">OUTPUT & DIAGNOSTICS</label><button type="button" id="clear-console">Clear</button></div><div class="execution-meta"><span id="execution-status" role="status" aria-live="polite" data-status="ready">Ready</span><span id="execution-duration"></span></div><pre id="run-output" aria-label="Program output" class="empty-output" tabindex="0">Output will appear here.</pre><pre id="run-errors" aria-label="Compiler and runtime diagnostics" class="run-errors" tabindex="0" hidden></pre></div></div><p class="execution-note">${['java','python'].includes(item.language)?'Runs on this computer through the local compiler server.':'Runs in an isolated browser worker.'} Ctrl/Cmd + Enter runs code. Esc leaves the editor. Runs have time and output limits.</p></section>`;};
 window.PrepEditor={beforeRender(){if(active)stop(true);if(editor){editor.toTextArea();editor=null;}mountedItem=null;},mount(){const item=currentItem(),textarea=document.querySelector('#lab-answer,#code-draft');if(!item?.programming||!textarea||!document.getElementById('run-code'))return;mountedItem=item;const panel=document.querySelector('.execution-panel'),container=textarea.parentElement;for(const selector of ['.execution-toolbar','.editor-tools']){const controls=panel.querySelector(selector);if(controls)container.insertBefore(controls,textarea);}if(window.CodeMirror){editor=CodeMirror.fromTextArea(textarea,{mode:mode[item.language],lineNumbers:true,indentUnit:item.language==='javascript'||item.language==='typescript'?2:4,tabSize:4,indentWithTabs:false,matchBrackets:true,autoCloseBrackets:true,styleActiveLine:true,inputStyle:'contenteditable',lineWrapping:false,viewportMargin:20,extraKeys:{'Ctrl-Enter':run,'Cmd-Enter':run,Tab:'indentMore','Shift-Tab':'indentLess',Esc:()=>document.getElementById('run-code').focus()}});const field=editor.getInputField();field.setAttribute('aria-label',languageConfig[item.language].name+' code editor');field.setAttribute('role','textbox');field.setAttribute('aria-multiline','true');editor.on('change',()=>{textarea.value=editor.getValue();state.drafts[keyFor(item)]=editor.getValue();persist();lineStatus();});editor.on('cursorActivity',lineStatus);requestAnimationFrame(()=>{editor?.refresh();lineStatus();});}paint(item,results.get(keyFor(item))||{status:'ready',stdout:'',stderr:''});},getValue};
 document.addEventListener('click',event=>{if(event.target.closest('#run-code'))run();if(event.target.closest('#stop-code'))stop();if(event.target.closest('#clear-console')&&mountedItem){results.set(keyFor(mountedItem),{status:active?'running':'ready',stdout:'',stderr:''});paint(mountedItem,results.get(keyFor(mountedItem)));}if(event.target.closest('#load-demo')&&mountedItem)setCode(demo(mountedItem.language),'10 20');if(event.target.closest('#load-solution')&&mountedItem?.code)setCode(mountedItem.code,'');if(event.target.closest('#restore-code')&&mountedItem){const code=state.editorBackups?.[keyFor(mountedItem)];if(code===undefined){toast('No earlier draft to restore.');return;}const current=getValue();editor?.setValue(code);state.editorBackups[keyFor(mountedItem)]=current;persist();toast('Earlier draft restored.');}if(event.target.closest('#download-code')&&mountedItem){const url=URL.createObjectURL(new Blob([getValue()],{type:'text/plain'}));const link=document.createElement('a');link.href=url;link.download=filename(mountedItem);link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
 document.addEventListener('input',event=>{if(event.target.id==='program-stdin'&&mountedItem){state.drafts[stdInputKey(mountedItem)]=event.target.value;persist();}});
})();
